import{_ as e,o as d,c as r,a4 as n}from"./chunks/framework.BMj-uaUw.js";const g=JSON.parse('{"title":"综合项目 · 校园活动服务平台","description":"","frontmatter":{},"headers":[{"level":2,"title":"这是什么项目","slug":"这是什么项目","link":"#这是什么项目","children":[]},{"level":2,"title":"谁在用","slug":"谁在用","link":"#谁在用","children":[]},{"level":2,"title":"主线流程","slug":"主线流程","link":"#主线流程","children":[]},{"level":2,"title":"五个功能模块","slug":"五个功能模块","link":"#五个功能模块","children":[]},{"level":2,"title":"这份规格文档怎么用","slug":"这份规格文档怎么用","link":"#这份规格文档怎么用","children":[]},{"level":2,"title":"参考实现","slug":"参考实现","link":"#参考实现","children":[]},{"level":2,"title":"技术约束","slug":"技术约束","link":"#技术约束","children":[]},{"level":2,"title":"交付要求","slug":"交付要求","link":"#交付要求","children":[]},{"level":2,"title":"三阶段节奏","slug":"三阶段节奏","link":"#三阶段节奏","children":[]},{"level":2,"title":"评分维度","slug":"评分维度","link":"#评分维度","children":[]}],"relativePath":"project/index.md","filePath":"project/index.md","lastUpdated":1789500889000}'),a={name:"project/index.md"};function i(o,t,l,h,s,p){return d(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="综合项目-·-校园活动服务平台" tabindex="-1">综合项目 · 校园活动服务平台 <a class="header-anchor" href="#综合项目-·-校园活动服务平台" aria-label="Permalink to &quot;综合项目 · 校园活动服务平台&quot;">​</a></h1><p>这一部分是综合项目的<strong>规格文档</strong>。它不是教程，是你们做项目时要照着执行的约定。</p><h2 id="这是什么项目" tabindex="-1">这是什么项目 <a class="header-anchor" href="#这是什么项目" aria-label="Permalink to &quot;这是什么项目&quot;">​</a></h2><p><strong>校园活动服务平台</strong> —— 给学生会、社团、学院教务处使用的活动管理平台，有两个端：</p><table tabindex="0"><thead><tr><th>端</th><th>谁用</th><th>形态</th></tr></thead><tbody><tr><td><strong>管理端</strong></td><td>组织者、审核员</td><td>电脑上的 Web 后台</td></tr><tr><td><strong>用户端</strong></td><td>学生</td><td>手机上的 H5 / 微信小程序</td></tr></tbody></table><p>学生用手机报名，组织者在电脑上发布活动、审核报名、安排场次。系统负责三件事：</p><ol><li>让活动从创建到结束有一个清晰的状态流程</li><li>让名额和报名数之间保持一致</li><li>让同一个场地在同一个时段不出现冲突</li></ol><p><strong>两个端共用一套后端接口。</strong> 管理端是 12 周课时的主体；用户端不占课时，是管理端跑通之后的第二个端，规格见<a href="/frontend-engineering-course/project/mobile.html">用户端需求规格</a>，做法见<a href="/frontend-engineering-course/mobile/">用户端 · uni-app 实战</a>。</p><h2 id="谁在用" tabindex="-1">谁在用 <a class="header-anchor" href="#谁在用" aria-label="Permalink to &quot;谁在用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>日常做什么</th><th>系统里的权限</th></tr></thead><tbody><tr><td>活动组织者</td><td>发布活动、看报名情况、审核报名、安排场次</td><td>只能看和管理自己的活动</td></tr><tr><td>审核员</td><td>审核所有活动的报名、维护场地信息</td><td>能看所有活动，能审核任何报名</td></tr><tr><td>学生</td><td>在手机上浏览活动、报名、查看审核结果</td><td>登录用户端；只能看到自己的报名记录，只能取消自己的报名</td></tr></tbody></table><p>学生的报名数据由后端提供。<strong>管理端只读这些数据</strong>（在列表里看到学生信息、报名记录）， <strong>用户端负责产生这些数据</strong>（提交报名、取消报名）。</p><h2 id="主线流程" tabindex="-1">主线流程 <a class="header-anchor" href="#主线流程" aria-label="Permalink to &quot;主线流程&quot;">​</a></h2><p>整条业务主线只有三步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 活动发布            ② 报名审核              ③ 场次安排</span></span>
<span class="line"><span>组织者创建活动         学生报名后组织者审核      通过审核的学生参加</span></span>
<span class="line"><span>设置名额与截止时间      通过则占用一个名额        安排时段与场地</span></span>
<span class="line"><span>发布后学生可报名        驳回则释放名额            检测时段冲突</span></span></code></pre></div><p><strong>这条主线必须在项目里完整跑通。</strong> 其余功能（数据看板、场地维护）是围绕主线的辅助功能。</p><h2 id="五个功能模块" tabindex="-1">五个功能模块 <a class="header-anchor" href="#五个功能模块" aria-label="Permalink to &quot;五个功能模块&quot;">​</a></h2><p>管理端按业务拆成五个模块：</p><table tabindex="0"><thead><tr><th>模块</th><th>主要页面</th><th>涉及角色</th><th>依赖</th></tr></thead><tbody><tr><td>登录鉴权</td><td>登录页</td><td>全部</td><td>无</td></tr><tr><td>活动管理</td><td>活动列表、详情、新增、编辑</td><td>组织者、审核员</td><td>登录鉴权</td></tr><tr><td>报名审核</td><td>报名列表、某活动的报名</td><td>组织者、审核员</td><td>活动管理</td></tr><tr><td>场次与场地</td><td>场地列表、场次安排</td><td>组织者、审核员</td><td>活动管理</td></tr><tr><td>数据看板</td><td>看板首页</td><td>组织者、审核员</td><td>上述全部</td></tr></tbody></table><p>用户端拆分方式不一样，它按学生的一次完整动作来分，只有 5 个页面：</p><table tabindex="0"><thead><tr><th>页面</th><th>学生在这一页干什么</th></tr></thead><tbody><tr><td>活动列表</td><td>找活动，支持搜索和下拉刷新</td></tr><tr><td>活动详情</td><td>看活动的完整信息与剩余名额</td></tr><tr><td>报名表单</td><td>填联系方式与备注，提交报名</td></tr><tr><td>我的报名</td><td>看自己所有报名的审核状态，能取消</td></tr><tr><td>个人中心</td><td>登录、退出、看个人信息</td></tr></tbody></table><p>两边的拆分依据为什么不同，见<a href="/frontend-engineering-course/project/mobile.html">用户端需求规格</a>的“页面清单”一节。</p><h2 id="这份规格文档怎么用" tabindex="-1">这份规格文档怎么用 <a class="header-anchor" href="#这份规格文档怎么用" aria-label="Permalink to &quot;这份规格文档怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>什么时候看</th><th>回答什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/project/requirements.html">管理端需求规格</a></td><td>动手之前</td><td>要做哪些功能、有哪些字段、界面大概是什么样</td></tr><tr><td><a href="/frontend-engineering-course/project/mobile.html">用户端需求规格</a></td><td>做手机端之前</td><td>学生端做哪 5 个页面、字段怎么定、验收标准</td></tr><tr><td><a href="/frontend-engineering-course/project/rules.html">业务规则与状态流转</a></td><td>写每一段业务逻辑之前</td><td>状态怎么变、名额怎么算、冲突怎么判断</td></tr><tr><td><a href="/frontend-engineering-course/project/api.html">接口约定</a></td><td>写 api 层之前</td><td>接口路径、参数、返回结构、错误码（含学生端接口）</td></tr><tr><td><a href="/frontend-engineering-course/project/structure.html">目录结构与命名约定</a></td><td>建工程之前</td><td>文件放哪、怎么命名、命名规范</td></tr><tr><td><a href="/frontend-engineering-course/project/milestones.html">三阶段交付</a></td><td>每周开始之前</td><td>这周要交什么、做到什么程度算完成</td></tr><tr><td><a href="/frontend-engineering-course/project/ai-collaboration.html">AI 协作规范</a></td><td>每次让 AI 参与之前</td><td>怎么描述任务、怎么审 AI 的代码、交付时要声明什么</td></tr></tbody></table><h2 id="参考实现" tabindex="-1">参考实现 <a class="header-anchor" href="#参考实现" aria-label="Permalink to &quot;参考实现&quot;">​</a></h2><p>写完规格之后，<a href="/frontend-engineering-course/project/impl-activity.html">参考实现</a>部分给出了各模块的逐模块写法：关键决策、数据流、代码结构、容易出问题的地方。</p><p><strong>参考实现不是让你照抄。</strong> 它是“如果你卡住了，可以看看别人怎么拆”的备用方案。<strong>先自己写一遍，写不下去了再对照。</strong> 直接抄的结果是答辩时讲不出来。</p><p>管理端：</p><table tabindex="0"><thead><tr><th>模块</th><th>参考实现</th></tr></thead><tbody><tr><td>登录与鉴权</td><td><a href="/frontend-engineering-course/project/impl-auth.html">impl-auth</a></td></tr><tr><td>活动管理</td><td><a href="/frontend-engineering-course/project/impl-activity.html">impl-activity</a></td></tr><tr><td>报名审核</td><td><a href="/frontend-engineering-course/project/impl-signup.html">impl-signup</a></td></tr><tr><td>场次与场地</td><td><a href="/frontend-engineering-course/project/impl-session.html">impl-session</a></td></tr><tr><td>数据看板</td><td><a href="/frontend-engineering-course/project/impl-dashboard.html">impl-dashboard</a></td></tr></tbody></table><p>用户端：</p><table tabindex="0"><thead><tr><th>模块</th><th>参考实现</th><th>对应的教程篇目</th></tr></thead><tbody><tr><td>登录与登录态</td><td><a href="/frontend-engineering-course/project/impl-mobile-auth.html">impl-mobile-auth</a></td><td><a href="/frontend-engineering-course/mobile/06-request-auth.html">6. 请求封装与登录态</a></td></tr><tr><td>活动浏览与报名</td><td><a href="/frontend-engineering-course/project/impl-mobile-browse.html">impl-mobile-browse</a></td><td><a href="/frontend-engineering-course/mobile/07-list-detail.html">7. 列表页与详情页</a></td></tr><tr><td>报名与我的报名</td><td><a href="/frontend-engineering-course/project/impl-mobile-signup.html">impl-mobile-signup</a></td><td><a href="/frontend-engineering-course/mobile/08-signup-form.html">8. 报名表单与我的报名</a></td></tr></tbody></table><h2 id="技术约束" tabindex="-1">技术约束 <a class="header-anchor" href="#技术约束" aria-label="Permalink to &quot;技术约束&quot;">​</a></h2><p>规格文档不规定技术选型，但课程有一条基线，不符合的要提前说明理由。</p><p><strong>管理端：</strong></p><table tabindex="0"><thead><tr><th>类别</th><th>基线</th></tr></thead><tbody><tr><td>框架</td><td>Vue 3.5，组合式 API</td></tr><tr><td>构建</td><td>Vite 8.3</td></tr><tr><td>路由</td><td>Vue Router 5.3</td></tr><tr><td>状态</td><td>Pinia 4.0</td></tr><tr><td>UI 库</td><td>Element Plus 2.14</td></tr><tr><td>请求</td><td>axios 1.20</td></tr><tr><td>包管理</td><td>pnpm</td></tr></tbody></table><p><strong>用户端：</strong></p><table tabindex="0"><thead><tr><th>类别</th><th>基线</th></tr></thead><tbody><tr><td>跨端框架</td><td>uni-app（<strong>经典版</strong>，不是 uni-app x）</td></tr><tr><td>脚手架</td><td>CLI 方式，基于 Vite（<code>uni-preset-vue#vite</code>）</td></tr><tr><td>构建</td><td>Vite 5.2（官方模板锁定，不要手动升到 8）</td></tr><tr><td>框架</td><td>Vue 3.4（同上，模板锁定）</td></tr><tr><td>路由</td><td><code>pages.json</code> 配置式，用 <code>uni.navigateTo</code> 等 API，<strong>不用 vue-router</strong></td></tr><tr><td>状态</td><td>不引入 Pinia，用 <code>uni.storage</code> + 工具函数</td></tr><tr><td>UI 库</td><td>Wot UI（<code>@wot-ui/ui</code>）</td></tr><tr><td>请求</td><td><code>uni.request</code> 自封装（沿用管理端的五个设计）</td></tr></tbody></table><p>用户端的版本看起来比管理端旧，这不是配置失误 —— uni-app 官方模板锁定了 Vite 5 与 Vue 3.4， 跨端编译器与其版本是绑定的，手动升级会直接编译失败。原因见<a href="/frontend-engineering-course/mobile/">用户端总览</a>。</p><p>完整的版本清单见<a href="/frontend-engineering-course/appendix/tools.html">工具链与版本清单</a>。</p><p><strong>为什么要有这条基线</strong>：全班用同一套技术栈，遇到问题时同学之间能互相帮忙，老师也能快速定位。<strong>如果你的项目有特殊理由要用别的技术（比如你们组已经熟悉 Ant Design Vue），提前说明即可，不是硬性要求。</strong></p><h2 id="交付要求" tabindex="-1">交付要求 <a class="header-anchor" href="#交付要求" aria-label="Permalink to &quot;交付要求&quot;">​</a></h2><p>项目结束时需要交这些东西：</p><table tabindex="0"><thead><tr><th>交付物</th><th>要求</th><th>对应哪一节</th></tr></thead><tbody><tr><td>线上可访问的地址</td><td>能登录、能操作主线功能、子路由刷新不 404</td><td><a href="/frontend-engineering-course/unit12/03-deploy.html">12.3 部署上线</a></td></tr><tr><td>Git 仓库</td><td>提交历史清晰、有 <code>.gitignore</code>、README 完整</td><td><a href="/frontend-engineering-course/unit12/04-delivery.html">12.4 交付材料与答辩</a></td></tr><tr><td>README</td><td>含运行方式、测试账号、已知问题</td><td><a href="/frontend-engineering-course/unit12/04-delivery.html">12.4</a></td></tr><tr><td>设计文档</td><td>含数据模型、状态机、关键决策及代价</td><td><a href="/frontend-engineering-course/unit11/practice.html">选做 3</a></td></tr><tr><td>接口文档</td><td>含错误码表</td><td><a href="/frontend-engineering-course/unit12/01-integration.html">练习 3</a></td></tr><tr><td>部署文档</td><td>含 Nginx 配置与更新步骤</td><td><a href="/frontend-engineering-course/unit12/03-deploy.html">练习 1</a></td></tr><tr><td>开发记录</td><td>含联调问题表与踩坑分析</td><td><a href="/frontend-engineering-course/unit12/04-delivery.html">练习 2</a></td></tr><tr><td>优化记录</td><td>含前后对比数据</td><td><a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2 构建优化</a></td></tr><tr><td>答辩 PPT</td><td>5 到 8 页，含一页技术难点</td><td><a href="/frontend-engineering-course/unit12/04-delivery.html">12.4</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">做了用户端的话，多交两样</p><p>前端工程化开发 48 学时<strong>不要求</strong>做用户端，它是延伸内容。如果你们组做了，把下面两项一起交：</p><ul><li>用户端的访问方式：H5 线上地址，或小程序的体验版二维码（答辩演示用体验版就够）</li><li>README 里补一段用户端的运行方式：<code>pnpm dev:h5</code> 与 <code>pnpm dev:mp-weixin</code> 分别是做什么的</li></ul><p>不做用户端<strong>不影响</strong>上面那几项的评分。做了的话，答辩时能多讲一个技术难点（跨端适配），是加分项。</p></div><h2 id="三阶段节奏" tabindex="-1">三阶段节奏 <a class="header-anchor" href="#三阶段节奏" aria-label="Permalink to &quot;三阶段节奏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>对应单元</th><th>交付什么</th></tr></thead><tbody><tr><td>阶段一 · 立项与骨架</td><td>单元 1 到 3</td><td>页面清单、接口清单、工程骨架、代码规范配置</td></tr><tr><td>阶段二 · 功能实现</td><td>单元 4 到 10</td><td>各模块页面与逻辑，单元 5 到 10 的案例直接对应项目模块</td></tr><tr><td>阶段三 · 交付</td><td>单元 11 到 12</td><td>完整主线功能、优化数据、线上地址、交付文档</td></tr><tr><td>（延伸）用户端</td><td>阶段三之后</td><td>5 个页面 + H5 或小程序发布，不占课时</td></tr></tbody></table><p>详细的阶段划分和每周检查点见<a href="/frontend-engineering-course/project/milestones.html">三阶段交付</a>。</p><h2 id="评分维度" tabindex="-1">评分维度 <a class="header-anchor" href="#评分维度" aria-label="Permalink to &quot;评分维度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>权重</th><th>看什么</th></tr></thead><tbody><tr><td>功能完整度</td><td>30%</td><td>主线三步能不能完整走通，边界情况处理了没有</td></tr><tr><td>工程质量</td><td>25%</td><td>目录结构、代码组织、命名、有没有大量重复代码</td></tr><tr><td>工程化实践</td><td>20%</td><td>版本控制、代码规范、构建优化、部署上线</td></tr><tr><td>文档质量</td><td>15%</td><td>README 能不能让人跑起来，设计文档有没有取舍分析</td></tr><tr><td>答辩表现</td><td>10%</td><td>能不能讲清一个技术难点，能不能回答提问</td></tr></tbody></table><p><strong>“工程质量”占 25%，比多数人预期的高。</strong> 它不是看你的功能多不多，是看代码能不能给别的人看。</p><p>下一步：<a href="/frontend-engineering-course/project/requirements.html">管理端需求规格</a>。做手机端的看<a href="/frontend-engineering-course/project/mobile.html">用户端需求规格</a>。</p>`,50)])])}const u=e(a,[["render",i]]);export{g as __pageData,u as default};
